#!/usr/bin/env python3
"""Milestone M11: preference post-training by DPO (docs/decisao_preferencia.md).

Subcommands:
    candidatos  prefixes of --palavras words drawn from the training partition, --K continuations of
                --tokens tokens each generated by the reference run; writes preferencia/candidatos_<modo>.json
    pares       the pairs of every prefix ranked by a source: "programatica" (attested word trigrams
                capped at the human test mean plus lexicon rate, candidates copying more than k words
                ranked last) or "embaralhada" (the programmatic pairs with labels flipped at random);
                writes preferencia/pares_<fonte>_<modo>.json
    dpo         trains a copy of the reference on the non-held-out pairs; writes runs/<run_id>/
    medir       held-out preference accuracy, per-token KL to the reference on held-out continuations
                and attested-trigram rate of fresh generations; writes runs/<run_id>/medida.json
    dose        gate P-dose: dpo + medir for the programmatic and the shuffled pairs over --sementes
                seeds, paired difference with a t interval

    python scripts/m11.py candidatos --modo autoregressivo --referencia <run_id> --dispositivo cuda
    python scripts/m11.py pares --modo autoregressivo --fonte programatica
    python scripts/m11.py dose --modo autoregressivo --sementes 5 --dispositivo cuda
"""
import argparse
import copy
import json
import random
import re
import sys
from pathlib import Path

import numpy as np
import torch

RAIZ = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(RAIZ))
from slm import leitura as lt  # noqa: E402
from slm.config import Config  # noqa: E402
from slm.corpus import ler_documentos, pasta_tokenizador  # noqa: E402
from slm.geracao import ate_eos, gerar_ar, gerar_difusao  # noqa: E402
from slm.modelo import ConfigRede, Transformer  # noqa: E402
from slm.perda import entrada_ar  # noqa: E402
from slm.preferencia import mascaras_y, montar_janelas, perda_dpo  # noqa: E402
from slm.mascaramento import mascarar  # noqa: E402
from slm.tokenizador import carregar_tokenizador  # noqa: E402

PASTA = RAIZ / "preferencia"
CAMPOS = set(Config.__dataclass_fields__)
PALAVRA = re.compile(r"\S+")


def carregar_corrida(run_id: str, dispositivo: str):
    pasta = RAIZ / "runs" / run_id
    bruto = json.loads((pasta / "config.json").read_text(encoding="utf-8"))
    cfg = Config.de_dicionario({k: v for k, v in bruto.items() if k in CAMPOS})
    modelo = Transformer(ConfigRede(vocab_size=cfg.vocab_size, L=cfg.L, n_layer=cfg.n_layer, d=cfg.d, n_head=cfg.n_head))
    modelo.load_state_dict(torch.load(pasta / "pesos.pt", map_location="cpu"))
    return cfg, bruto, modelo.to(dispositivo).eval(), carregar_tokenizador(pasta_tokenizador(cfg))


def excertos(textos, n, palavras, semente):
    rng = random.Random(semente)
    toks = [PALAVRA.findall(t) for t in textos]
    inicios = [(i, j) for i, tk in enumerate(toks) for j in range(len(tk) - palavras + 1)]
    return [" ".join(toks[i][j:j + palavras]) for i, j in rng.sample(inicios, n)]


def texto_de(tok, ids):
    return tok.decode(ate_eos([i for i in ids if i > 3 or i == 2])).decode("utf-8", "replace")


def cmd_candidatos(a):
    cfg, _, modelo, tok = carregar_corrida(a.referencia, a.dispositivo)
    treino = [d["texto"] for d in ler_documentos(cfg.corpus, "treino")]
    prefixos = excertos(treino, a.prefixos + a.retidos, a.palavras, a.semente)
    saida = []
    for i, px in enumerate(prefixos):
        ids = tok.encode(px)[-(cfg.L - a.tokens):]
        semente = 1000 * a.semente + i
        if cfg.modo == "autoregressivo":
            w = gerar_ar(modelo, len(ids) + a.tokens, n=a.K, prefixo=ids, semente=semente, dispositivo=a.dispositivo)
        else:
            w = gerar_difusao(modelo, cfg.L, T_gen=a.t_gen or cfg.L, n=a.K, prefixo=ids, semente=semente, dispositivo=a.dispositivo)
        cands = [ate_eos(r[len(ids): len(ids) + a.tokens]) for r in w.tolist()]
        saida.append({"prefixo": px, "ids": ids, "retido": i >= a.prefixos,
                      "candidatos": [{"ids": c, "texto": texto_de(tok, c)} for c in cands]})
    PASTA.mkdir(exist_ok=True)
    (PASTA / f"candidatos_{cfg.modo}.json").write_text(json.dumps(
        {"referencia": a.referencia, "modo": cfg.modo, "prefixos": saida}, ensure_ascii=False), encoding="utf-8")
    print(f"{len(saida)} prefixos, {a.K} candidatos cada, em preferencia/candidatos_{cfg.modo}.json")


def cmd_pares(a):
    cand = json.loads((PASTA / f"candidatos_{a.modo}.json").read_text(encoding="utf-8"))
    if a.fonte == "embaralhada":
        base = json.loads((PASTA / f"pares_programatica_{a.modo}.json").read_text(encoding="utf-8"))
        rng = random.Random(a.semente)
        pares = [dict(p, g=p["p"], p=p["g"]) if rng.random() < 0.5 else p for p in base["pares"]]
        info = {"origem": "pares_programatica com rotulos trocados com probabilidade 1/2", "semente": a.semente}
    elif a.fonte == "programatica":
        cfg, _, _, _ = carregar_corrida(cand["referencia"], "cpu")
        treino = [d["texto"] for d in ler_documentos(cfg.corpus, "treino")]
        teste = [d["texto"] for d in ler_documentos(cfg.corpus, "teste")]
        tri, lex, indice = lt.trigramas(treino), lt.lexico(treino), lt.IndiceTreino(treino)
        n_pal = int(np.median([len(PALAVRA.findall(c["texto"])) for p in cand["prefixos"] for c in p["candidatos"]]))
        hum = excertos(teste, 500, max(3, n_pal), a.semente)
        a3_h = float(np.nanmean([lt.taxa_trigramas(t, tri) for t in hum]))
        lex_h = float(np.nanmean([lt.taxa_lexico(t, lex) for t in hum]))
        k = lt.limiar_copia(indice.maiores_trechos(hum))
        pares = []
        for i, p in enumerate(cand["prefixos"]):
            r = []
            for c in p["candidatos"]:
                a3, lx = lt.taxa_trigramas(c["texto"], tri), lt.taxa_lexico(c["texto"], lex)
                copia = indice.maior_trecho(c["texto"]) if c["texto"] else 0
                r.append(-np.inf if np.isnan(a3) or np.isnan(lx) or copia > k else min(a3, a3_h) + min(lx, lex_h))
            for g in range(len(r)):
                for q in range(len(r)):
                    if r[g] > r[q]:
                        pares.append({"prefixo": i, "g": g, "p": q, "retido": p["retido"]})
        info = {"palavras_humanas": n_pal, "a3_humano": a3_h, "lex_humano": lex_h, "k": k}
    else:
        sys.exit("fonte humana: carregar as ordenacoes dos avaliadores (a implementar com o formato da coleta)")
    (PASTA / f"pares_{a.fonte}_{a.modo}.json").write_text(json.dumps({"fonte": a.fonte, **info, "pares": pares}, ensure_ascii=False), encoding="utf-8")
    print(json.dumps({"fonte": a.fonte, "pares": len(pares), "retidos": sum(p["retido"] for p in pares), **info}, default=float))


def janelas(cand, pares, L):
    x = [cand["prefixos"][p["prefixo"]]["ids"] for p in pares]
    yg = [cand["prefixos"][p["prefixo"]]["candidatos"][p["g"]]["ids"] for p in pares]
    yp = [cand["prefixos"][p["prefixo"]]["candidatos"][p["p"]]["ids"] for p in pares]
    return montar_janelas(x, yg, L), montar_janelas(x, yp, L)


def cmd_dpo(a):
    cand = json.loads((PASTA / f"candidatos_{a.modo}.json").read_text(encoding="utf-8"))
    pares = [p for p in json.loads((PASTA / f"pares_{a.fonte}_{a.modo}.json").read_text(encoding="utf-8"))["pares"] if not p["retido"]]
    cfg, bruto, ref, _ = carregar_corrida(cand["referencia"], a.dispositivo)
    pol = copy.deepcopy(ref).train()
    lr = a.lr if a.lr else cfg.lr * cfg.lr_min_frac
    opt = torch.optim.AdamW(pol.parameters(), lr=lr, betas=tuple(cfg.betas), weight_decay=0.0)
    rng = random.Random(a.semente)
    g = torch.Generator().manual_seed(a.semente)
    registro = []
    for ep in range(a.epocas):
        ordem = pares[:]
        rng.shuffle(ordem)
        for s in range(0, len(ordem), a.lote):
            (wg, mg), (wp, mp) = janelas(cand, ordem[s:s + a.lote], cfg.L)
            perda, marg, acc = perda_dpo(pol, ref, wg.to(a.dispositivo), mg.to(a.dispositivo), wp.to(a.dispositivo),
                                         mp.to(a.dispositivo), cfg.modo, a.beta, n=a.n, gerador=g)
            opt.zero_grad()
            perda.backward()
            torch.nn.utils.clip_grad_norm_(pol.parameters(), cfg.clip)
            opt.step()
            registro.append({"epoca": ep, "passo": len(registro), "perda": float(perda.detach()), "acuracia": acc,
                             "margem_media": float(marg.mean())})
    pasta = RAIZ / "runs" / a.run_id
    if pasta.exists():
        sys.exit(f"{pasta} exists: runs are never overwritten")
    pasta.mkdir(parents=True)
    torch.save(pol.state_dict(), pasta / "pesos.pt")
    (pasta / "config.json").write_text(json.dumps({**bruto, "run_id": a.run_id, "papel": "preferencia", "extra": {
        **(bruto.get("extra") or {}), "dpo": {"referencia": cand["referencia"], "fonte": a.fonte, "beta": a.beta, "lr": lr,
                                              "epocas": a.epocas, "lote": a.lote, "n": a.n, "semente": a.semente,
                                              "pares_treino": len(pares)}}}, indent=1, ensure_ascii=False), encoding="utf-8")
    (pasta / "passos.jsonl").write_text("".join(json.dumps(r) + "\n" for r in registro), encoding="utf-8")
    print(a.run_id, "| passos", len(registro), "| perda final", round(registro[-1]["perda"], 4), "| acuracia final", registro[-1]["acuracia"])


@torch.no_grad()
def kl_por_token(pol, ref, modo, w, m_y, g):
    if modo == "autoregressivo":
        lp, lr = torch.log_softmax(pol(entrada_ar(w), True).double(), -1), torch.log_softmax(ref(entrada_ar(w), True).double(), -1)
        pos = m_y
    else:
        masc = mascaras_y(m_y, 1, g)[0].to(w.device)
        lp, lr = torch.log_softmax(pol(mascarar(w, masc), False).double(), -1), torch.log_softmax(ref(mascarar(w, masc), False).double(), -1)
        pos = masc
    p = lp.exp()
    kl = torch.where(p > 0, p * (lp - lr), torch.zeros_like(p)).sum(-1)  # the [MASK] logit is -inf in both models
    return float(kl[pos].mean())


def cmd_medir(a):
    cand = json.loads((PASTA / f"candidatos_{a.modo}.json").read_text(encoding="utf-8"))
    retidos = [p for p in json.loads((PASTA / f"pares_programatica_{a.modo}.json").read_text(encoding="utf-8"))["pares"] if p["retido"]]
    cfg, _, ref, tok = carregar_corrida(cand["referencia"], a.dispositivo)
    _, _, pol, _ = carregar_corrida(a.run_id, a.dispositivo)
    g = torch.Generator().manual_seed(a.semente)
    (wg, mg), (wp, mp) = janelas(cand, retidos, cfg.L)
    wg, mg, wp, mp = (t.to(a.dispositivo) for t in (wg, mg, wp, mp))
    with torch.no_grad():
        _, marg, acc = perda_dpo(pol, ref, wg, mg, wp, mp, cfg.modo, 1.0, n=16, gerador=g)
    kl = kl_por_token(pol, ref, cfg.modo, wg, mg, g)
    treino = [d["texto"] for d in ler_documentos(cfg.corpus, "treino")]
    tri = lt.trigramas(treino)
    prefixos = [p for p in cand["prefixos"] if p["retido"]]
    a3_pol, a3_ref = [], []
    for i, p in enumerate(prefixos):
        n_tok = max(len(c["ids"]) for c in p["candidatos"]) or 1
        if cfg.modo == "autoregressivo":
            w = gerar_ar(pol, len(p["ids"]) + n_tok, n=2, prefixo=p["ids"], semente=7000 + i, dispositivo=a.dispositivo)
        else:
            w = gerar_difusao(pol, cfg.L, T_gen=cfg.L, n=2, prefixo=p["ids"], semente=7000 + i, dispositivo=a.dispositivo)
        a3_pol += [lt.taxa_trigramas(texto_de(tok, r[len(p["ids"]): len(p["ids"]) + n_tok]), tri) for r in w.tolist()]
        a3_ref += [lt.taxa_trigramas(c["texto"], tri) for c in p["candidatos"]]
    res = {"acuracia_retida": acc, "margem_retida_media": float(marg.mean()), "kl_por_token": kl,
           "a3_politica": float(np.nanmean(a3_pol)), "a3_referencia": float(np.nanmean(a3_ref))}
    (RAIZ / "runs" / a.run_id / "medida.json").write_text(json.dumps(res, indent=1), encoding="utf-8")
    print(a.run_id, json.dumps({k: round(v, 4) for k, v in res.items()}))
    return res


def cmd_dose(a):
    from scipy.stats import t as student
    linhas = {"programatica": [], "embaralhada": []}
    for s in range(a.sementes):
        for fonte in linhas:
            rid = f"m11-dose-{a.modo[:3]}-{fonte}-e{a.epocas}-s{s}"
            if not (RAIZ / "runs" / rid / "medida.json").exists():
                if not (RAIZ / "runs" / rid).exists():
                    cmd_dpo(argparse.Namespace(**{**vars(a), "fonte": fonte, "semente": s, "run_id": rid}))
                cmd_medir(argparse.Namespace(**{**vars(a), "run_id": rid, "semente": s}))
            linhas[fonte].append(json.loads((RAIZ / "runs" / rid / "medida.json").read_text()))
    saida = {}
    for m in ("kl_por_token", "acuracia_retida", "a3_politica"):
        d = np.array([p[m] - e[m] for p, e in zip(linhas["programatica"], linhas["embaralhada"])])
        meia = student.ppf(0.975, len(d) - 1) * d.std(ddof=1) / np.sqrt(len(d)) if len(d) > 1 else float("nan")
        saida[m] = {"diferencas": d.round(5).tolist(), "media": float(d.mean()), "ic95": [float(d.mean() - meia), float(d.mean() + meia)]}
    aprovado = all(saida[m]["ic95"][0] > 0 for m in ("kl_por_token", "acuracia_retida"))
    saida["aprovado"] = aprovado
    PASTA.mkdir(exist_ok=True)
    (PASTA / f"dose_{a.modo}_e{a.epocas}.json").write_text(json.dumps(saida, indent=1), encoding="utf-8")
    print(json.dumps(saida, indent=1))


def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="etapa", required=True)
    s = sub.add_parser("candidatos")
    s.add_argument("--referencia", required=True)
    s.add_argument("--prefixos", type=int, default=125)
    s.add_argument("--retidos", type=int, default=25)
    s.add_argument("--palavras", type=int, default=30)
    s.add_argument("--K", type=int, default=4)
    s.add_argument("--tokens", type=int, default=96)
    s.add_argument("--t-gen", type=int, default=0)
    s.add_argument("--semente", type=int, default=0)
    s.add_argument("--dispositivo", default="cpu")
    s = sub.add_parser("pares")
    s.add_argument("--modo", required=True)
    s.add_argument("--fonte", choices=["programatica", "embaralhada", "humana"], required=True)
    s.add_argument("--semente", type=int, default=0)
    for nome in ("dpo", "dose"):
        s = sub.add_parser(nome)
        s.add_argument("--modo", required=True)
        s.add_argument("--beta", type=float, default=0.1)
        s.add_argument("--epocas", type=int, default=1)
        s.add_argument("--lote", type=int, default=64)
        s.add_argument("--lr", type=float, default=0.0, help="default: lr_min of the reference")
        s.add_argument("--n", type=int, default=8)
        s.add_argument("--dispositivo", default="cpu")
        if nome == "dpo":
            s.add_argument("--fonte", required=True)
            s.add_argument("--semente", type=int, default=0)
            s.add_argument("--run-id", required=True)
        else:
            s.add_argument("--sementes", type=int, default=5)
    s = sub.add_parser("medir")
    s.add_argument("--modo", required=True)
    s.add_argument("--run-id", required=True)
    s.add_argument("--semente", type=int, default=0)
    s.add_argument("--dispositivo", default="cpu")
    a = ap.parse_args()
    {"candidatos": cmd_candidatos, "pares": cmd_pares, "dpo": cmd_dpo, "medir": cmd_medir, "dose": cmd_dose}[a.etapa](a)


if __name__ == "__main__":
    main()
